1	import React, { useState, useEffect, useRef } from 'react';
2	import { Search, Check, AlertCircle, X, Sparkles } from 'lucide-react';
3	
4	export interface CharacterSearchResult {
5	  id: string;
6	  char_code: string;
7	  canonical_name: string;
8	  series: string;
9	  avatar_url?: string;
10	  hazard_score?: number;
11	  hazard_class?: string;
12	}
13	
14	interface CharacterIdSelectorProps {
15	  value: string; // The char_code e.g. 'A01'
16	  displayName?: string;
17	  avatarUrl?: string;
18	  onSelect: (character: CharacterSearchResult) => void;
19	  placeholder?: string;
20	  disabled?: boolean;
21	}
22	
23	const FALLBACK_AVATAR = "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Crect width='100' height='100' fill='%231a1f3a'/%3E%3Ctext x='50' y='55' font-size='32' text-anchor='middle' fill='%23d4af37' font-family='monospace'%3E%3F%3C/text%3E%3C/svg%3E";
24	
25	export const CharacterIdSelector: React.FC<CharacterIdSelectorProps> = ({
26	  value,
27	  displayName,
28	  avatarUrl,
29	  onSelect,
30	  placeholder = 'Type Character ID (e.g. A01)...',
31	  disabled = false,
32	}) => {
33	  const [query, setQuery] = useState(value || '');
34	  const [isOpen, setIsOpen] = useState(false);
35	  const [results, setResults] = useState<CharacterSearchResult[]>([]);
36	  const [isLoading, setIsLoading] = useState(false);
37	  const [selectedIndex, setSelectedIndex] = useState(0);
38	  const [isValidMatch, setIsValidMatch] = useState(true);
39	
40	  const wrapperRef = useRef<HTMLDivElement>(null);
41	  const inputRef = useRef<HTMLInputElement>(null);
42	
43	  // Sync external value
44	  useEffect(() => {
45	    setQuery(value || '');
46	  }, [value]);
47	
48	  // Search characters with debounce
49	  useEffect(() => {
50	    let active = true;
51	    const fetchMatches = async () => {
52	      setIsLoading(true);
53	      try {
54	        const res = await fetch(`/api/characters?q=${encodeURIComponent(query)}&limit=15`);
55	        if (res.ok && active) {
56	          const data: CharacterSearchResult[] = await res.json();
57	          setResults(data);
58	          setSelectedIndex(0);
59	
60	          // Validate if exact match exists when query is non-empty
61	          if (query.trim()) {
62	            const hasExact = data.some(
63	              (c) => c.char_code.toUpperCase() === query.trim().toUpperCase()
64	            );
65	            setIsValidMatch(hasExact);
66	          } else {
67	            setIsValidMatch(true);
68	          }
69	        }
70	      } catch (e) {
71	        console.error('[CharacterIdSelector] Search error:', e);
72	      } finally {
73	        if (active) setIsLoading(false);
74	      }
75	    };
76	
77	    const timer = setTimeout(fetchMatches, 150);
78	    return () => {
79	      active = false;
80	      clearTimeout(timer);
81	    };
82	  }, [query]);
83	
84	  // Click outside to close
85	  useEffect(() => {
86	    const handleClickOutside = (e: MouseEvent) => {
87	      if (wrapperRef.current && !wrapperRef.current.contains(e.target as Node)) {
88	        setIsOpen(false);
89	      }
90	    };
91	    document.addEventListener('mousedown', handleClickOutside);
92	    return () => document.removeEventListener('mousedown', handleClickOutside);
93	  }, []);
94	
95	  const handleSelect = (char: CharacterSearchResult) => {
96	    setQuery(char.char_code);
97	    setIsValidMatch(true);
98	    setIsOpen(false);
99	    onSelect(char);
100	  };
101	
102	  const handleKeyDown = (e: React.KeyboardEvent) => {
103	    if (!isOpen) {
104	      if (e.key === 'ArrowDown' || e.key === 'Enter') {
105	        setIsOpen(true);
106	      }
107	      return;
108	    }
109	
110	    if (e.key === 'ArrowDown') {
111	      e.preventDefault();
112	      setSelectedIndex((prev) => (prev + 1 < results.length ? prev + 1 : 0));
113	    } else if (e.key === 'ArrowUp') {
114	      e.preventDefault();
115	      setSelectedIndex((prev) => (prev - 1 >= 0 ? prev - 1 : results.length - 1));
116	    } else if (e.key === 'Enter') {
117	      e.preventDefault();
118	      if (results[selectedIndex]) {
119	        handleSelect(results[selectedIndex]);
120	      }
121	    } else if (e.key === 'Escape') {
122	      setIsOpen(false);
123	    }
124	  };
125	
126	  return (
127	    <div className="relative w-full" ref={wrapperRef}>
128	      {/* Input Box with Character ID, Name preview & Status */}
129	      <div
130	        className={`flex items-center gap-2 px-3 py-1.5 rounded-xl border bg-hazard-void transition ${
131	          !isValidMatch && query.trim()
132	            ? 'border-hazard-crimson ring-1 ring-hazard-crimson/50'
133	            : isOpen
134	            ? 'border-hazard-gold ring-1 ring-hazard-gold/40'
135	            : 'border-hazard-border hover:border-hazard-borderHover'
136	        }`}
137	      >
138	        {/* Avatar Thumbnail */}
139	        <div className="w-7 h-7 rounded-lg overflow-hidden shrink-0 border border-hazard-border bg-hazard-card">
140	          <img
141	            src={avatarUrl || FALLBACK_AVATAR}
142	            alt="Avatar"
143	            className="w-full h-full object-cover"
144	            onError={(e) => {
145	              (e.target as HTMLImageElement).src = FALLBACK_AVATAR;
146	            }}
147	          />
148	        </div>
149	
150	        {/* Text Input */}
151	        <input
152	          ref={inputRef}
153	          type="text"
154	          value={query}
155	          disabled={disabled}
156	          onChange={(e) => {
157	            setQuery(e.target.value);
158	            setIsOpen(true);
159	          }}
160	          onFocus={() => setIsOpen(true)}
161	          onKeyDown={handleKeyDown}
162	          placeholder={placeholder}
163	          className="flex-1 bg-transparent text-xs font-mono font-bold text-hazard-gold placeholder:text-hazard-textMuted/40 uppercase outline-none"
164	        />
165	
166	        {/* Resolved Name Readout if available */}
167	        {displayName && (
168	          <span className="text-[11px] font-bold text-hazard-textBright truncate max-w-[130px] hidden sm:inline">
169	            {displayName}
170	          </span>
171	        )}
172	
173	        {/* Invalid ID Badge */}
174	        {!isValidMatch && query.trim() && (
175	          <span
176	            title="Character ID not found in SQLite database. Options are strictly restricted to registered characters."
177	            className="flex items-center gap-1 text-[10px] font-mono font-bold text-hazard-crimson bg-hazard-crimson/15 px-1.5 py-0.5 rounded border border-hazard-crimson/30"
178	          >
179	            <AlertCircle className="w-3 h-3" />
180	            <span>Not in DB</span>
181	          </span>
182	        )}
183	      </div>
184	
185	      {/* Auto-Suggest Dropdown List (Options restricted strictly to SQLite) */}
186	      {isOpen && (
187	        <div className="absolute left-0 right-0 top-full mt-1.5 z-50 max-h-60 overflow-y-auto rounded-2xl bg-hazard-card border-2 border-hazard-border shadow-2xl p-1.5 flex flex-col gap-1 animate-fadeIn">
188	          {isLoading && results.length === 0 ? (
189	            <div className="p-3 text-center text-xs font-mono text-hazard-textMuted">
190	              Querying character registry...
191	            </div>
192	          ) : results.length === 0 ? (
193	            <div className="p-3 text-center text-xs font-mono text-hazard-crimson flex flex-col items-center gap-1">
194	              <AlertCircle className="w-4 h-4" />
195	              <span>No character found with ID "{query.toUpperCase()}"</span>
196	              <span className="text-[10px] text-hazard-textMuted/60">
197	                (Strict constraint: Only pre-registered character IDs can be chosen)
198	              </span>
199	            </div>
200	          ) : (
201	            results.map((char, idx) => {
202	              const isSelected = idx === selectedIndex;
203	              const isExact = char.char_code.toUpperCase() === query.trim().toUpperCase();
204	
205	              return (
206	                <div
207	                  key={char.id}
208	                  onClick={() => handleSelect(char)}
209	                  onMouseEnter={() => setSelectedIndex(idx)}
210	                  className={`flex items-center justify-between p-2 rounded-xl cursor-pointer transition select-none ${
211	                    isSelected
212	                      ? 'bg-hazard-cardHover text-white ring-1 ring-hazard-gold/50'
213	                      : 'hover:bg-hazard-void/80 text-hazard-textBright'
214	                  }`}
215	                >
216	                  <div className="flex items-center gap-2.5 min-w-0">
217	                    <img
218	                      src={char.avatar_url || FALLBACK_AVATAR}
219	                      alt={char.canonical_name}
220	                      className="w-8 h-8 rounded-lg object-cover border border-hazard-border shrink-0"
221	                      onError={(e) => {
222	                        (e.target as HTMLImageElement).src = FALLBACK_AVATAR;
223	                      }}
224	                    />
225	                    <div className="flex flex-col min-w-0">
226	                      <div className="flex items-center gap-1.5">
227	                        <span className="font-mono font-bold text-xs text-hazard-gold bg-hazard-gold/15 px-1.5 py-0.2 rounded border border-hazard-gold/30">
228	                          {char.char_code}
229	                        </span>
230	                        <span className="text-xs font-bold text-hazard-textBright truncate">
231	                          {char.canonical_name}
232	                        </span>
233	                      </div>
234	                      {char.series && (
235	                        <span className="text-[10px] font-mono text-hazard-textMuted truncate">
236	                          {char.series}
237	                        </span>
238	                      )}
239	                    </div>
240	                  </div>
241	
242	                  {/* Hazard Score Pill */}
243	                  <div className="flex items-center gap-2 shrink-0 ml-2">
244	                    {char.hazard_score !== undefined && (
245	                      <span className="text-[10px] font-mono font-bold px-2 py-0.5 rounded-full bg-hazard-void border border-hazard-border text-hazard-cyan">
246	                        ★ {Number(char.hazard_score).toFixed(1)}
247	                      </span>
248	                    )}
249	                    {isExact && <Check className="w-4 h-4 text-hazard-gold" />}
250	                  </div>
251	                </div>
252	              );
253	            })
254	          )}
255	        </div>
256	      )}
257	    </div>
258	  );
259	};
